'use strict';
function twinSelectReturn(id){if(twinState.mode==='workflow'){twinState.choice=id;showTraveler();updateTwinScene();}else{const r=twinState.result.example.items.find(r=>r.id===id);if(!r)return;$('#twin-sidebar').innerHTML=`<span class="tag">Simulated item</span><h2>${esc(r.id)}</h2><p>This item belongs only to this scenario.</p><dl><dt>Arrival</dt><dd>${r.arrival.toFixed(0)} min</dd><dt>Exception hold</dt><dd>${r.hold?'Yes':'No'}</dd><dt>Completion</dt><dd>${r.finished.toFixed(0)} min</dd></dl><button class="secondary" id="back-scenario">Back to variables</button>`;$('#back-scenario').onclick=showScenario;}}
window.addEventListener('twin-pallet-pick',e=>twinSelectReturn(e.detail));window.addEventListener('twin-station-pick',e=>showStation(e.detail));
showTraveler=function(){const r=records.find(r=>r.id===twinState.choice)||records[0];twinState.choice=r.id;const issues=openIssues(r),stage=r.stage;
 $('#twin-sidebar').innerHTML=`<div class="traveler-title"><span class="traveler-icon">▣</span> Digital Traveler</div><div class="traveler-id"><h2>${esc(r.id)}</h2>${statusTag(r)}</div><p class="traveler-product">${esc(r.product)}</p><div class="traveler-tabs"><button id="twin-traveler-tab" aria-pressed="true">Traveler</button><button id="twin-history-tab" aria-pressed="false">History</button></div><div id="twin-traveler-detail"><dl class="traveler-facts"><dt>Location</dt><dd>${issues.length?'Exception Hold':STAGES[stage]}</dd><dt>Owner</dt><dd>${esc(r.owner)}</dd><dt>Next step</dt><dd>${issues.length?'Resolve exception':stage===4?'Completed':STAGES[stage+1]}</dd></dl><h3 class="traveler-section-title">Workflow</h3><div class="traveler-steps">${['Receiving','Inspection','Disposition','Handoff'].map((s,i)=>`<div class="${i<stage?'done':i===stage?'current':''}"><i>${i<stage?'✓':''}</i><strong>${s}</strong><small>${i<stage?'Completed':i===stage?'Current':'Pending'}</small></div>`).join('')}</div>${issues.map(e=>`<div class="traveler-exception"><span>⚠</span><div><strong>${esc(e.title)}</strong><p>Owner review and a resolution note are required before progression.</p></div></div>`).join('')}<div class="traveler-actions">${issues.length?`<button class="primary" data-open="${esc(r.id)}" data-tab="exceptions">Review exception</button>`:''}<button class="secondary" data-open="${esc(r.id)}">Open full traveler</button></div><div class="traveler-assistant"><h3>✧ Workflow assistant</h3><div class="traveler-question">Why is this return ${issues.length?'blocked':'at this stage'}?</div><p>${issues.length?esc(issues.map(e=>e.title).join('; '))+'. '+esc(issues[0].owner)+' owns the first exception.':esc(r.owner)+' owns this return at '+STAGES[stage]+'. Review its traveler before advancing.'}</p><small>Rule-based guidance using current browser records.</small></div></div>`;
 const detail=$('#twin-traveler-detail'),html=detail.innerHTML;$('#twin-history-tab').onclick=()=>{$('#twin-history-tab').setAttribute('aria-pressed','true');$('#twin-traveler-tab').setAttribute('aria-pressed','false');detail.innerHTML=`<div class="timeline">${[...r.events].reverse().map(e=>`<div class="event"><strong>${esc(e.text)}</strong><small>${esc(e.actor)} · ${date(e.at)}</small></div>`).join('')}</div>`;};$('#twin-traveler-tab').onclick=()=>{$('#twin-traveler-tab').setAttribute('aria-pressed','true');$('#twin-history-tab').setAttribute('aria-pressed','false');detail.innerHTML=html;};$('#twin-comparison').innerHTML='';
};
const beforePolishRender=render;
render=function(){const active=(location.hash.slice(1)||'overview')==='twin';document.body.classList.toggle('twin-active',active);beforePolishRender();if(!active)return;
 const stats=document.createElement('div');stats.className='twin-summary';const activeRecords=records.filter(r=>r.stage<4);stats.innerHTML=[['↶','Active returns',activeRecords.length],['⚠','Blocked',activeRecords.filter(r=>openIssues(r).length).length],['⇥','Ready for handoff',activeRecords.filter(r=>r.stage===3&&!openIssues(r).length).length]].map(([icon,label,n])=>`<div><span class="summary-symbol">${icon}</span><span>${label}<strong>${n}</strong></span></div>`).join('');$('.twin-layout').before(stats);
 for(const [id,action] of [['twin-left','left'],['twin-right','right'],['twin-zoom','zoom'],['twin-reset-view','reset']])$('#'+id).onclick=()=>window.dispatchEvent(new CustomEvent('twin-camera',{detail:action}));$('#twin-left').textContent='↶ Rotate';$('#twin-right').textContent='↷';
};
render();
